export interface LibraryCard {
  question: string;
  answer: string;
}

export interface LibraryDeck {
  slug: string;
  title: string;
  subject: string;
  topic: string;
  cards: LibraryCard[];
}

function deck(
  slug: string,
  title: string,
  subject: string,
  topic: string,
  cards: LibraryCard[]
): LibraryDeck {
  return { slug, title, subject, topic, cards };
}

